const cache = new Map();
const hex = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];

// One frame of a sprite as a canvas at 1x, cached per frame and time of day.
export function frame(name, i = 0, night = false) {
    const key = `${name}|${i}|${night}`;
    let c = cache.get(key);
    if (c) return c;
    const s = ART[name];
    const pal = (night ? s.night : s.day).map(hex);
    c = document.createElement("canvas");
    c.width = s.w;
    c.height = s.h;
    const ctx = c.getContext("2d");
    const img = ctx.createImageData(s.w, s.h);
    s.frames[i % s.frames.length].split("|").forEach((row, y) => {
        let x = 0;
        for (let k = 0; k < row.length; k += 2) {
            const n = A.indexOf(row[k]), idx = A.indexOf(row[k + 1]);
            if (idx > 0) {
                const [r, g, b] = pal[idx - 1];
                for (let j = 0; j < n; j++) {
                    const o = (y * s.w + x + j) * 4;
                    img.data[o] = r; img.data[o + 1] = g; img.data[o + 2] = b; img.data[o + 3] = 255;
                }
            }
            x += n;
        }
    });
    ctx.putImageData(img, 0, 0);
    cache.set(key, c);
    return c;
}
